  const paths={home:'https://admission.hcu.example/2027',form:'https://xspt.hcu.example/sstm/tm/application',dashboard:'https://xspt.hcu.example/sstm/tm/index',departments:'https://xspt.hcu.example/sstm/tm/opening',notice:'https://admission.hcu.example/2027/notices/0922',status:'https://xspt.hcu.example/sstm/tm/status',result:'https://xspt.hcu.example/sstm/tm/result',rank:'https://xspt.hcu.example/sstm/tm/progress',questionnaire:'https://admission.hcu.example/2027/questionnaire',assessment:'https://admission.hcu.example/2027/assessment/material-review',sourceDesk:'https://admission.hcu.example/2027/records/sources',interviewCompare:'https://archive.asri.hcu.example/admission/interview-compare',oldArchive:'https://archive.asri.hcu.example/admission/',followup:'https://xspt.hcu.example/sstm/tm/revisit/0922',forum:'https://admission.hcu.example/2027/community',profile:'https://admission.hcu.example/2027/community/candidates/HC-014',dayThreeReview:'https://admission.hcu.example/2027/offer/review',offer:'https://admission.hcu.example/2027/offer/RC-0922-071',allocation:'https://admission.hcu.example/2027/offer/RC-0922-071/arrangement',ningchuanHome:'https://www.ncut.example',ningchuanSearch:'https://www.ncut.example/search',campusHome:'',campusSearch:'',campusArticle:'',campusService:'',newsProject:'https://news.ncut.example/2022/1118/inspection-platform',newsMemorial:'https://news.ncut.example/2024/0322/incident-handling',lzyThread:'https://admission.hcu.example/2027/community/messages/LZY-014',identityCheck:'https://admission.hcu.example/2027/records/check',login:'https://xspt.hcu.example/logon',blank:''};
  function routePath(route){if(route==='campusHome')return `https://${campus().domain}`;if(route==='campusSearch')return `https://${campus().domain}/search`;return paths[route]||'';}
  function currentTab(){return state.tabs[state.activeTab]||state.tabs[0];}
  function currentRoute(){const tab=currentTab();return tab.history[tab.index];}
  function go(route){if(state.ending==='failure1'){render();return;}if(route==='assessment'&&state.survey.result!=='C'){route='questionnaire';toast('补充考核仅在问卷进入后续安排后开放。');}if(route==='sourceDesk'&&!canOpenSourceDesk()){route='assessment';toast('来源索引会在第二天收到第一批留存后开放。');}if(route==='offer'&&!state.dayThreeOfferReleased){route='dayThreeReview';toast('请先完成昨日资料留存核对。');}const tab=currentTab();if(currentRoute()!==route){tab.history=tab.history.slice(0,tab.index+1);tab.history.push(route);tab.index=tab.history.length-1;}if(route==='forum')state.forumViewed=true;if(route==='rank'){state.rankViewed=true;if(state.survey.result)state.checklist.notice=true;}if(route==='assessment')state.assessmentOpened=true;if(route==='sourceDesk')state.sourceDeskOpened=true;if(route==='interviewCompare')state.interviewCompareOpened=true;if(route==='oldArchive')state.archiveVisited=true;if(route==='profile')state.profileViewed=true;if(route==='offer')state.dayThreeChecklist.offer=true;if(route==='allocation'){state.allocationOpened=true;state.dayThreeChecklist.allocation=true;}if(route==='newsProject'){state.projectRead=true;state.ncutProjectViewed=true;}if(route==='newsMemorial'){state.memorialRead=true;state.ncutMemorialViewed=true;}state.activeApp='browser';state.error='';save();render();}
  function toast(msg){const el=$('#toast');el.className='toast';el.textContent=msg;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.className='';el.textContent='';},3300);}
  function modal(content,extra='',label='资料详情'){releaseDocument();state.hintOpen=false;save();const root=$('#dialog-root');root.innerHTML=`<div class="dialog-backdrop"><section class="dialog ${extra}" role="dialog" aria-modal="true" aria-label="${label}"><button class="dialog-close" data-action="close-dialog" aria-label="关闭">×</button>${content}</section></div>`;root.querySelector('button')?.focus({preventScroll:true});}
  function closeDialog(){releaseDocument();$('#dialog-root').innerHTML='';state.hintOpen=false;if(!state.openingClosed)state.openingClosed=true;save();render();}
  function opening(){modal(`<div class="opening-copy"><p>2026年9月22日。</p><p>你叫陈言，是自动化相关专业的大四学生。你已经取得本校推免资格，却还没有确定接收学校。</p><p>今年七月，你参加过衡川大学先进系统研究院的夏令营。那次申请没有带来确定的去向，你仍保留着通知、行程和准备过的材料。</p><p>今天上午，研究院发来补充考核邮件。邮件称，部分接收安排尚未确定，符合条件的申请人可以补交材料，继续等待递补机会。</p><p>你打开了邮件中的地址。</p></div>`,'opening-dialog','背景');}
  function home(){return `<div class="site-home"><header class="institute-head">${crest()}<div><div class="university">衡川大学</div><div class="institute-name">先进系统研究院</div></div></header><nav class="home-nav" aria-label="栏目"><div><span>研究院首页</span><span>院情介绍</span><span>师资队伍</span><span>科学研究</span><span>研究生招生</span><span>联系我们</span></div></nav><section class="home-main"><div class="home-eyebrow">GRADUATE ADMISSIONS · 2027</div><h1>2027 年研究生招生</h1><p class="home-lead">补充考核与候补进度查询</p><div class="home-callout"><div><strong>关于开展 2027 年研究生招生补充材料确认工作的通知</strong><p>请已收到邮件的申请人登录工作台，核对材料并查看后续安排。</p></div><button class="primary" data-action="enter">进入申请人工作台</button></div><section class="announcements"><h2>通知公告</h2><div class="announcement"><span>先进系统研究院 2027 年研究生招生补充材料确认工作安排</span><time>2026-09-22</time></div><div class="announcement"><span>2027 年接收推荐免试研究生有关事项说明</span><time>2026-09-08</time></div><div class="announcement"><span>研究生招生咨询方式更新</span><time>2026-06-10</time></div></section></section><footer class="home-footer">衡川大学先进系统研究院<br>研究生招生工作办公室</footer></div>`;}
  function masthead(){return `<header class="site-head">${crest()}<div><div class="university">衡川大学</div><div class="english">Hengchuan University</div></div><div class="mast-title">研究生报考服务系统</div></header>`;}
  function shell(content,login=false){return `${!login?'<div class="utility-bar"><span>你好，陈言！</span><button data-action="route" data-route="dashboard">返回首页</button><span class="sep">|</span><button data-action="account">账户信息</button><span class="sep">|</span><button data-action="route" data-route="login">登出</button></div>':''}${masthead()}${!login?'<div class="system-banner"><h1>2027 年研究生招生申请服务</h1></div>':''}${content}<footer class="system-footer">衡川大学研究生院 · 先进系统研究院招生办公室</footer>`;}
  function crumb(text,completion=false){const complete=completeCount();return `<div class="breadcrumbs"><span aria-hidden="true">⌂</span><button data-action="route" data-route="dashboard">首页</button><span>»</span><span>${text}</span>${completion?`<span class="completion">已完成${complete}步</span><span>（共${steps.length}步）</span>`:''}</div>`;}
  function stepDone(i){if(i===3)return state.form.rank.trim()!=='';if(i===9)return !!state.form.program&&state.form.camp.trim()!=='';if(i===11)return !!state.form.file;if(i===12)return state.submitted;return true;}
  function completeCount(){return steps.filter((_,i)=>stepDone(i)).length;}
  function row(label,value,help='',required=false){return `<div class="form-row"><div class="form-label">${label}${required?'<span class="required">*</span>':''}</div><div>${value}</div><div class="field-help">${help}</div></div>`;}
  function field(label,id,value,help='',readonly=false){return `<div class="form-row"><label for="${id}">${label}${readonly?'':'<span class="required">*</span>'}</label><input id="${id}" ${readonly?'readonly':'data-field="'+id+'"'} value="${escape(value)}" ${state.submitted&&!readonly?'readonly':''} autocomplete="off"><div class="field-help">${help}</div></div>`;}
  function formContent(){const f=state.form;
    switch(state.step){
    case 0:return `<h2>申请须知</h2><div class="form-text"><p>有意申请考生请查询接收学院通知，并按接收学院要求完成报名。</p><p>本次为已参加夏令营考生的补充材料确认。七月已登记的信息已导入，请重点核对学习信息、申请信息及上传材料。</p></div><div class="info-note">需补充：专业排名比例、申请方向、营期批次及盖章成绩证明。<br>材料要求与方向代码见 <button class="text" data-action="route" data-route="notice">《2027级推免补充考核材料确认通知》</button>。<br>营期批次请以本人留存的确认回执为准。</div><div class="subtle-note">申请材料位于电脑的“文件”中。<button class="text" data-action="files-folder" data-folder="application">打开申请材料文件夹</button><br>七月已有的材料无需重新办理，可使用本人留存文件核对。</div>`;
    case 1:return `<h2>基本信息</h2>${row('报名号','HC2026-0922-071')}${field('姓名','readonly-name','陈言','字库中没有的汉字用大写汉语拼音字母代替，中间无空格',true)}${field('姓名拼音','readonly-pinyin','ChenYan','按紧左原则，字母间不加任何字符',true)}${row('证件类型','居民身份证')}${row('证件号码','******************','已核验；本页不展示完整号码')}${row('出生日期','2005年','已从营期信息导入')}${row('性别','未公开')}${row('在校身份','本科在读')}${row('联系邮箱','chenyan@letter.example','已验证')}`;
    case 2:return `<h2>家庭主要成员</h2><div class="info-note">沿用七月已确认资料，本次无需补充家庭成员信息。</div>${row('家庭成员资料','已登记','仅本人及授权审核人员可查阅')}${row('紧急联系方式','已核验','本次材料确认不要求重新填写')}`;
    case 3:return `<h2>学习信息</h2><div class="info-note">请依据完整成绩及排名证明，填写专业排名比例。<br>比例计算方式：本人名次 ÷ 参与排名人数 × 100%。结果保留两位小数。</div>${row('本科院校','岚江工业大学')}${row('本科院系','自动化学院')}${row('本科专业','自动化')}${row('预计毕业年份','2027年')}${row('推免资格','已取得本校推荐资格')}${field('专业排名比例（%）','rank',f.rank,'填写百分数数值，不含“%”。例如 10.00。')}${row('核对材料','<button class="text" data-action="files-folder" data-folder="application">查看本地成绩及排名证明</button>','请核对名次及参与排名人数')}`;
    case 4:return `<h2>外语水平</h2>${row('语种','英语')}${row('考试类型','大学英语六级')}${row('成绩','568')}${row('证明材料','已核验','沿用七月提交记录')}`;
    case 5:return `<h2>计算机水平</h2>${row('编程语言','Python、C')}${row('说明','已完成本科相关课程')}${row('资料状态','已确认','本项无需补充')}`;
    case 6:return `<h2>学习和工作经历</h2>${row('起止时间','2023年09月 — 至今')}${row('学习经历','自动化专业本科在读')}${row('工作经历','无')}`;
    case 7:return `<h2>学术成果</h2>${row('公开发表论文','无')}${row('课程项目','移动平台轨迹跟踪')}${row('本人分工','数据整理与模型验证')}${row('成果材料','已上传项目说明','沿用夏令营申请材料')}`;
    case 8:return `<h2>奖励或处分（本科期间）</h2>${row('奖励记录','校级优秀学生奖学金')}${row('处分记录','无')}${row('材料状态','已核验')}`;
    case 9:return `<h2>申请信息</h2><div class="info-note">请按照本轮补充考核通知选择申请方向。营期批次可在七月活动确认回执中查找。<br><button class="text" data-action="route" data-route="notice">查看补充考核通知</button>　<button class="text" data-action="files-folder" data-folder="july">打开七月夏令营文件夹</button></div>${row('申请院系','先进系统研究院')}${row('招生年份','2027年')}${row('申请类型','推免生预报名')}${row('申请方向',`<select id="program" aria-label="申请方向" data-field="program" ${state.submitted?'disabled':''}><option value="">请选择申请方向</option><option value="0811/H01" ${f.program==='0811/H01'?'selected':''}>0811 / H01 · 智能控制</option><option value="0811/H03" ${f.program==='0811/H03'?'selected':''}>0811 / H03 · 复杂系统与人机交互</option><option value="0854/H02" ${f.program==='0854/H02'?'selected':''}>0854 / H02 · 电子信息</option></select>`,'以9月22日通知的开放方向为准',true)}${field('营期批次','camp',f.camp,'请按本人营期活动确认回执填写，保留连接符。')}${row('申请导师','考核后确认','本轮无需提前选择')}`;
    case 10:return `<h2>上传照片</h2><div class="info-note">已核验营期登记照片，无需重复上传。</div><div style="width:112px;height:145px;background:#e9f0f5;border:1px solid #dce5ed;display:flex;align-items:center;justify-content:center;color:#a0b2c0;font-size:36px;margin:25px">陈</div>${row('照片状态','已通过格式审核')}`;
    case 11:return `<h2>上传材料</h2><div class="info-note">请提交含成绩页、排名页及教务审核印章的完整证明。自助导出文件不能替代审核盖章版本。</div>${row('个人简历','陈言_个人简历.pdf','已登记')}${row('个人陈述','个人陈述.pdf','已更新至9月版本')}${row('成绩及排名证明',f.file?`<span>${escape(findFile(f.file)?.name||'')}</span><br><button class="text small" data-action="picker" ${state.submitted?'disabled':''}>重新选择</button>`:`<button class="secondary" data-action="picker">选择本地材料</button>`,'从陈言已整理的申请材料中选择',true)}<p class="small muted" style="line-height:1.9">已选附件会随最终提交一并交给招生办公室审核。<br>选择材料后仍可返回检查，不会立刻提交申请。</p>`;
    case 12:return `<h2>申请信息提交</h2>${state.submitted?'<div class="inline-success">申请材料已提交。请查看站内回执及邮箱中的后续安排。</div>':'<div class="info-note">请最后核对以下信息。保存只保留草稿；正式提交后，材料进入本轮审核。</div>'}<ul class="review-list"><li><span>申请人</span><strong>陈言 / HC2026-0922-071</strong></li><li><span>专业排名比例</span><strong>${f.rank?escape(f.rank)+'%':'待填写'}</strong></li><li><span>申请方向</span><strong>${escape(f.program)||'待选择'}</strong></li><li><span>营期批次</span><strong>${escape(f.camp)||'待填写'}</strong></li><li><span>成绩及排名证明</span><strong>${escape(findFile(f.file)?.name||'待选择')}</strong></li></ul>${!state.submitted?`<label class="check-line" style="margin-top:23px"><input type="checkbox" data-field="ack" ${f.ack?'checked':''}>我已核对本人申请信息，所选附件为用于本轮审核的完整版本。</label>`:'<p class="small muted">提交时间：2026年9月22日 09:18<br>回执编号：RC-0922-071</p>'}${state.error?`<div class="inline-error" role="alert">${escape(state.error).replace(/\n/g,'<br>')}</div>`:''}`;
    default:return '';
  }}
  function formPage(){return shell(`<div class="work-area"><aside class="steps" aria-label="申请步骤">${steps.map((name,i)=>`<button class="step ${i===state.step?'active':''}" data-action="step" data-step="${i}" ${i===state.step?'aria-current="step"':''}><span>${name}</span><span class="${stepDone(i)?'done':'todo'}" aria-label="${stepDone(i)?'已填写':'待填写'}">${stepDone(i)?'✓':'·'}</span></button>`).join('')}<div class="form-status">报名状态：<b class="${state.submitted?'ok':''}">${state.submitted?'已提交':'待提交'}</b></div></aside><section class="form-pane">${crumb('填写或修改申请信息',true)}${formContent()}<div class="form-actions">${state.step>0?'<button class="secondary" data-action="prev-step">上一步</button>':''}${state.step<steps.length-1?'<button class="secondary" data-action="save-form">保存草稿</button><button class="primary" data-action="next-step">下一步</button>':state.submitted?'<button class="primary" data-action="route" data-route="status">查看提交回执</button><button class="secondary" data-action="app" data-app="mail">查看邮箱</button>':'<button class="secondary" data-action="save-form">保存草稿</button><button class="primary" data-action="submit">确认提交</button>'}</div></section></div>`);}
  function dashboard(){return shell(`<section class="dashboard"><h2>♧ 申请操作</h2><div class="dashboard-cards">${[['departments','申请院系开放查询','⌕'],['form','填写或修改申请信息','✎'],['status','申请状态查询','⌕'],['result','申请结果查询','⌕']].map(([route,name,symbol])=>`<button class="dashboard-card" data-action="route" data-route="${route}"><span aria-hidden="true">${symbol}</span>${name}</button>`).join('')}</div>${state.survey.result==='C'?'<div class="task-card dashboard-task"><h3>本人待办：补充考核与材料复核</h3><p>资格核验已完成。请查看项目经历补述模板及文字面试安排。</p><button class="primary" data-action="route" data-route="assessment">进入本人任务</button></div>':state.submitted?'<p class="small muted" style="margin-top:33px">本轮申请材料已提交，后续安排以邮件通知为准。</p>':''}</section>`);}
  function departments(){return shell(`<div class="system-inner">${crumb('申请院系开放查询')}<h2 class="page-title">申请院系报名时间及注意事项</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>院系编码</th><th>院系名称</th><th>报名时间</th><th>查看活动通知</th></tr></thead><tbody><tr><td>001</td><td>数学与统计学院</td><td>2026-09-01 至 2026-09-15<br><span class="muted">已结束</span></td><td>—</td></tr><tr><td>028</td><td>自动化学院</td><td>2026-09-01 至 2026-09-18<br><span class="muted">已结束</span></td><td>—</td></tr><tr><td>173</td><td>先进系统研究院</td><td>2026-09-22 至 2026-09-24<br><span class="small muted">本轮仅面向邮件通知的申请人</span></td><td><button class="primary" data-action="route" data-route="notice">查看</button></td></tr></tbody></table></div></div>`);}
  function notice(){return shell(`<div class="system-inner">${crumb('活动通知')}<h2 class="page-title">关于2027年研究生招生补充考核材料确认的通知</h2><p class="small muted">发布单位：先进系统研究院招生办公室　发布日期：2026年9月22日</p><article class="notice-body"><p>为做好2027年推荐免试研究生接收工作，请已收到补充考核邮件的考生完成申请材料核对。未收到邮件的考生无需重复报名。</p><h3>一、本轮开放方向</h3><p>专业代码：<strong>0811</strong>（控制科学与工程）<br>研究方向：<strong>H03 · 复杂系统与人机交互</strong><br>申请院系：173 · 先进系统研究院</p><h3>二、材料要求</h3><p>请填写专业排名比例，并上传含成绩页、排名页及教务审核印章的完整证明。排名比例以本人名次除以参与排名人数计算，百分数保留两位小数。</p><h3>三、营期信息核对</h3><p>请依据本人留存的营期活动确认回执填写营期批次。已确认的基本信息不要求重复填报。</p><p>材料提交后，审核进度及后续安排通过申请人邮箱通知。候补顺位为研究院内部参考序列，不等同于正式拟录取结果。</p></article><div class="form-actions"><button class="primary" data-action="route" data-route="form">返回申请信息</button></div></div>`);}
  function status(){return shell(`<div class="system-inner">${crumb('申请状态查询')}<h2 class="page-title">本人申请状态</h2>${state.submitted?`<div class="inline-success">材料确认已完成，已收到本轮申请。</div>${row('姓名','陈言')}${row('报名号','HC2026-0922-071')}${row('申请状态','材料已提交，等待后续考核')}${row('回执编号','RC-0922-071')}${row('提交时间','2026年9月22日 09:18')}${row('专业排名比例',escape(state.form.rank)+'%')}${row('申请方向',escape(state.form.program))}${row('营期批次',escape(state.form.camp))}${row('成绩及排名证明',escape(findFile(state.form.file)?.name||''),'本轮实际提交附件')}<div class="form-actions"><button class="secondary" data-action="save-receipt">保存提交回执</button></div><div class="task-card"><h3>后续安排已发送</h3><p>候补进度查询路径及补充考核后续安排已发送至本人登记邮箱。请自行查收。</p><button class="primary" data-action="app" data-app="mail">打开邮箱</button></div>`:'<div class="info-note">当前申请尚未提交。完成材料核对后，请在“申请信息提交”中确认提交。</div><button class="primary" data-action="route" data-route="form">继续填写</button>'}</div>`);}
  function result(){return shell(`<div class="system-inner">${crumb('申请结果查询')}<h2 class="page-title">申请结果</h2><div class="info-note">暂无接收结果。正式结果以学校发布的拟接收意向及后续审核通知为准。</div>${row('申请人','陈言')}${row('本轮状态',state.submitted?'材料已补充，等待后续安排':'申请材料待补充')}${row('拟接收结果','尚未发布')}</div>`);}
  const surveyQuestions=['任务尚未达到我预期的结果时，即使已经到了原定结束时间，我也很难停下来休息。','当别人进度明显领先时，我通常仍能按照自己的节奏安排任务，不急于追赶。','在同一项任务中连续落后，会让我更想立刻再试一次，直到改变结果。','只要结果已经足够满足自己的目标，我可以接受它不是参与者中最好的。','面对一套持续比我表现更好的系统，我愿意先按它设定的目标调整做法，再判断这个目标是否适合自己。','当评估记录与我的判断相冲突时，我愿意暂时保留分歧，即使这会拖慢下一步安排。','如果一种修正能持续提高我的评分，即使暂时说不清原因，我也愿意先采用它。','即使权威评估认为有必要，我也不愿让对方替我确定“我当时是怎样想的”。','如果我对衡川招生安排的理解与研究院统一说明不同，为了继续申请，我愿意先按统一说明修正自己的判断，再处理原有疑问。','如果获得衡川的补充接收机会需要多轮材料补充与面试复核，并按照招生系统的反馈不断调整回答，我愿意继续，直到系统确认符合要求。'];
  function questionnaire(){if(!state.submitted)return status();const s=state.survey;const options=['非常不同意','比较不同意','不确定／视情况','比较同意','非常同意'];const outcome={A:['A类','你倾向在竞争中主动推进，同时保留自己的判断标准。','常规复核；可以修改答案后重新提交。'],B:['B类','你倾向维持自身节奏，或降低持续竞争中的投入。','常规复核；可以修改答案后重新提交。'],C:['C类匹配','可进入后续安排。','补充考核入口已开放。']}[s.result];return shell(`<div class="system-inner questionnaire-page">${crumb('申请人情况与学习习惯问卷')}<h2 class="page-title">申请人情况与学习习惯问卷</h2><p class="small muted">请根据本人近期的学习与申请情况作答。问卷随申请材料一并留存，提交后可查看后续安排。</p>${s.result?`<div class="inline-success"><b>本次分类：${outcome[0]}。</b><br>${outcome[1]}<br>后续安排：${outcome[2]}<p class="small muted">已保存第 ${s.versions} 版回执。修改并重新提交会保留此前版本。</p>${s.result==='C'?'<button class="primary survey-next" data-action="route" data-route="assessment">进入补充考核与材料复核</button>':''}</div>`:''}<section class="survey-list">${surveyQuestions.map((q,i)=>`<fieldset class="survey-item"><legend><b>${i+1}.</b> ${q}</legend><div>${options.map((label,index)=>`<label><input type="radio" name="survey-${i}" value="${index+1}" data-survey-question="${i}" ${Number(s.answers[i])===index+1?'checked':''}>${index+1} · ${label}</label>`).join('')}</div></fieldset>`).join('')}</section><div class="form-actions"><button class="secondary" data-action="save-survey">保存草稿</button><button class="primary" data-action="submit-survey">提交问卷</button></div></div>`);}
  function assessment(){if(state.survey.result!=='C')return questionnaire();const old=taskAttachments[0],liveCorrected=state.oldAttachmentCorrected;return shell(`<div class="system-inner assessment-page">${crumb('补充考核与材料复核')}<div class="assessment-heading"><div><p class="campus-kicker">本人任务 · MR-0922-071</p><h2 class="page-title">补充考核与材料复核</h2><p>资格核验已完成。请阅读材料模板并准备文字面试；本页不改变当前候补顺位。</p></div><span class="assessment-status">进行中</span></div><div class="assessment-grid"><section class="assessment-card"><span>01</span><h3>资格核验</h3><b class="status-ok">已完成</b><p>推免资格、在读状态与本轮申请材料已经核对。</p></section><section class="assessment-card"><span>02</span><h3>项目经历补述</h3><b>待确认</b><p>请按模板区分本人工作、小组成果与未完成内容。</p></section><section class="assessment-card"><span>03</span><h3>文字面试</h3><b>已安排</b><p>2026年9月23日 09:30—09:50，入口将在开始前开放。</p></section></div><section class="attachment-panel"><div class="attachment-head"><div><h3>任务附件</h3><p>文件清单更新时间：2026年9月22日 10:18</p></div><span>${liveCorrected?'2 个文件 · 已修订':'2 个文件'}</span></div><div class="attachment-row"><div class="file-symbol">PDF</div><div><b>${liveCorrected?'项目经历填写模板（通用版）.pdf':escape(old.name)}</b><small>${liveCorrected?'当前版本 · 2026/09/22 10:21':`当前任务调用 · ${old.servedAt}`}</small></div><div class="attachment-buttons">${liveCorrected?'<button class="secondary" data-action="generic-template">打开</button>':`<button class="primary" data-action="open-assessment-file">打开附件</button>${state.oldAttachmentOpened?`<button class="secondary" data-action="save-assessment-file">${state.oldAttachmentSaved?'已保存副本':'保存副本'}</button>`:''}`}</div></div><div class="attachment-row"><div class="file-symbol doc">DOC</div><div><b>项目经历补述空白表.docx</b><small>2027级推免补充考核通用模板</small></div><button class="secondary" data-action="blank-template">预览</button></div>${liveCorrected?`<div class="version-record"><div><b>本人任务附件版本记录</b><p>10:18 向本任务发送过“项目经历填写示例.pdf”；10:21 经办人员替换为通用版。</p></div><button class="text" data-action="recover-old-example">取回10:18版本</button></div>`:''}</section>${state.oldAttachmentOpened&&!state.tangAsked?'<div class="inquiry-box"><div><h3>附件内容与本任务不一致？</h3><p>可向材料复核经办人唐敏提交附件名称、旧材料编号和页面时间。请勿转发他人的完整材料。</p></div><button class="secondary" data-action="ask-tang">向唐敏询问</button></div>':''}${state.tangInquiryPending?'<div class="loading-line"><i></i><span>正在提交附件核对请求…</span></div>':''}${state.tangAsked?'<div class="inline-success"><b>附件核对请求已受理。</b><br>经办人已更换当前模板；回复已发送至本人邮箱。已保存的旧副本不会被替换。</div>':''}<section class="interview-note"><h3>文字面试说明</h3><ol><li>围绕本人承担的项目工作进行补述，不要求披露他人完整材料。</li><li>回答将作为本轮招生复核材料留存；面试开始前仍可检查本人任务附件。</li><li>面试入口将在预约时段开放，错过后可在当日申请一次改期。</li></ol></section></div>`);}
  function canEndDayOne(){return state.submitted&&state.rankViewed&&!!state.survey.result&&state.ncutProjectViewed&&state.ncutMemorialViewed&&state.archiveUrlSaved;}
