    const sourceLink=canOpenSourceDesk()?'<button class="folder-button" data-action="route" data-route="sourceDesk">'+icon('document')+'<span>来源索引</span></button>':'';
    const compareLink=folder==='downloads'&&state.fanSecondPacketReceived?'<button class="folder-button" data-action="route" data-route="interviewCompare">'+icon('document')+'<span>访谈对照工作台</span></button>':'';
    const toolbarLink=folder==='downloads'&&state.fanSecondPacketReceived?'<span class="toolbar-action"><button class="text" data-action="route" data-route="interviewCompare">打开访谈对照</button></span>':'';
