  function memoTasks(){const isDayThree=state.day>=3,isDayTwo=state.day===2,items=isDayThree?dayThreeItems:(isDayTwo?dayTwoItems:dayOneItems),values=isDayThree?state.dayThreeChecklist:(isDayTwo?state.dayTwoChecklist:{...state.dayOneChecklist,...state.checklist}),done=items.filter(([key])=>values[key]).length;let heading='先把手头的材料弄好。';if(isDayThree){heading=state.dayThreeChecklist.allocation?'把预排记录和本人选择一起保存。':state.dayThreeChecklist.offer?'核对接收安排里的阶段字段。':state.dayThreeReviewSubmitted?'等待招生办公室完成接收意向核对。':'先确认昨日资料已经完整留存。';}else if(isDayTwo){heading=state.fanResponsibilityChecked?'把已经确认的记录链保存好。':state.fanModelIndexOpened?'追问范既白经手过的整理和上报。':state.fanComparisonComplete?'核验最后一页模型交接索引。':state.fanSecondPacketReceived?'把原始访谈和整理摘要并排核对。':state.fanFirstPacketReceived?'先分清三种编号分别标记什么。':'看看昨天保留的旧站地址。';}else if(state.sourceNoticeSent)heading='先把已经发现的资料记下来。';const dayLabel=isDayThree?'9月24日':isDayTwo?'9月23日':'9月22日';const prefix=isDayThree?'day-three-':isDayTwo?'day-two-':'day-one-';return `<section class="memo-checklist" aria-label="待办清单"><div class="memo-list-heading"><div><span class="memo-eyebrow">${dayLabel} · 今天</span><h2>${heading}</h2></div><span class="memo-count">${done} / ${items.length}</span></div><div class="memo-tasks">${items.map(([key,label])=>`<label class="memo-task ${values[key]?'is-done':''}"><input type="checkbox" data-${prefix}checklist="${key}" ${values[key]?'checked':''}><span>${label}</span></label>`).join('')}</div>${memoFindings()}${state.memoEggSeen?`<button class="memo-fold" data-action="memo-egg"><span>夹在清单后面的纸条</span><small>7月10日 · 写给九月的自己</small><span aria-hidden="true">↗</span></button>`:'<p class="memo-tip">完成流程后会自动更新；也可以手动划掉待办。</p>'}</section>`;}
