    'retry-survey'(){state.ending='';state.failedSurveyResult='';state.survey={answers:Array(10).fill(0),result:'',versions:state.survey.versions};state.activeApp='browser';state.tabs=[{history:['questionnaire'],index:0}];state.activeTab=0;state.scrollPositions={};save();render();},
